def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            v_without_build, build = v.rsplit('+', 1)
        else:
            v_without_build = v
            build = ''

        # Split pre-release
        if '-' in v_without_build:
            core, prerelease = v_without_build.split('-', 1)
        else:
            core = v_without_build
            prerelease = None

        # Parse core version
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            identifiers = prerelease.split('.')
            prerelease_list = []
            for ident in identifiers:
                if ident.isdigit():
                    prerelease_list.append((0, int(ident)))
                else:
                    prerelease_list.append((1, ident))
        else:
            prerelease_list = None

        return (major, minor, patch, prerelease_list)

    def compare_key(v):
        major, minor, patch, prerelease_list = parse_version(v)

        # If no pre-release, it sorts after with pre-release
        if prerelease_list is None:
            return (major, minor, patch, (1,), '')
        else:
            # Convert prerelease_list to a tuple for comparison
            return (major, minor, patch, (0,) + tuple(prerelease_list), '')

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=compare_key)

